/**
 * {@link RaceServiceImpl} 的 H2 数据库测试：主流程、失败分支与幂等边界。
 */
@SpringBootTest
@Import(FixedClockTestConfig.class)
class RaceServiceH2Test extends AbstractRaceH2Test {

    private static final String RACE = "race-1";

