package com.example.starter.race.domain;

/**
 * 队伍名单锁定状态。
 */
public enum TeamLockStatus {
    /** 名单已锁定，禁止普通增删成员。 */
    LOCKED,
    /** 名单未锁定，可维护成员；锁定被裁判解除后也回到该状态。 */
    UNLOCKED
}

package com.example.starter.race.persistence;

import com.example.starter.race.domain.TeamLockStatus;

/**
 * race_team 表行记录。
 *
 * @param raceId        所属赛事ID
 * @param teamId        队伍ID，同一赛事内唯一
 * @param captainBib    队长参赛号
 * @param status        名单锁定状态
 * @param rosterVersion 当前名单版本，0表示从未锁定
 * @param createdAt     创建时间，Unix毫秒时间戳
 * @param updatedAt     最近一次名单变更时间，Unix毫秒时间戳
 */
public record TeamRow(
        String raceId,
        String teamId,
        String captainBib,
        TeamLockStatus status,
        int rosterVersion,
        long createdAt,
        long updatedAt
) {
}

package com.example.starter.race.persistence;

/**
 * race_team_member 表行记录（队伍当前名单）。
 *
 * @param raceId    所属赛事ID
 * @param teamId    所属队伍ID
 * @param bib       成员参赛号；同一参赛者在同一赛事最多属于一支队伍
 * @param createdAt 加入时间，Unix毫秒时间戳
 */
public record TeamMemberRow(String raceId, String teamId, String bib, long createdAt) {
}

