                    repository.insertRosterLockMembers(raceId, lock.teamId(), rosterVersion, members);
                    repository.deleteTeamMembers(raceId, lock.teamId());
                    for (String bib : members) repository.insertTeamMember(raceId, lock.teamId(), bib, now);
