                .orElseThrow(() -> new ConflictException("队伍未处于锁定状态: " + teamId));
        long now = clock.millis();
        bumpVersion(race, request.expectedVersion());
        int updated = repository.markLockUnlocked(raceId, teamId, activeLock.rosterVersion(), request.reason(), now);
        if (updated == 0) throw new ConflictException("队伍未处于锁定状态: " + teamId);
        repository.updateTeamLockState(raceId, teamId, TeamLockStatus.UNLOCKED, team.rosterVersion(), now);
        return ServiceResult.ok(getRoster(raceId, teamId));
    });
