@Transactional(readOnly = true)
public RosterResponse getRoster(String raceId, String teamId) {
    RaceRow race = repository.findRace(raceId).orElseThrow(NotFound 赛事);
    TeamRow team = repository.findTeam(raceId, teamId).orElseThrow(NotFound 队伍);
    List<String> members = repository.findTeamMembers(raceId, teamId).stream().map(TeamMemberRow::bib).toList();
    Optional<RosterLockRow> latest = repository.findLatestLock(raceId, teamId);
    Long lockedAt = null; Integer lockRaceVersion = null; Long unlockedAt = null; String unlockReason = null;
    if (latest.isPresent()) {
        RosterLockRow lock = latest.get();
        if (lock.status() == TeamLockStatus.LOCKED) { lockedAt = lock.lockedAt(); lockRaceVersion = lock.raceVersion(); }
        else { unlockedAt = lock.unlockedAt(); unlockReason = lock.unlockReason(); }
    }
    return new RosterResponse(raceId, teamId, team.captainBib(), team.status(), team.rosterVersion(), members, race.version(), lockedAt, lockRaceVersion, unlockedAt, unlockReason);
}
```

