    }

    private static LockRostersRequest lockRequest(String requestId) {
        return new LockRostersRequest(
                List.of(new LockRostersRequest.TeamLockRequest("t1", "a", List.of("a", "b"))),
                4, requestId);
    }

    @Test
    void 并发同版本批量锁定仅一个成功且版本只加一() throws Exception {
        setupRaceWithTeam();

        int threads = 8;
