                    6, "req-lock-key")))
            .isInstanceOf(ConflictException.class);

    // 失败不占键：先以 req-lock-fail 提交非法名单（422），再用同键提交合法参数成功
    assertThatThrownBy(() -> raceService.lockRosters(RACE,
            new LockRostersRequest(List.of(lockOf("t1", "a", "a", "ghost")),
                    7, "req-lock-fail")))
            .isInstanceOf(UnprocessableEntityException.class);
    raceService.unlockRoster(RACE, "t1",
            new UnlockRosterRequest("解锁重锁", 7, nextRequestId()));
    LockRostersResponse retried = (LockRostersResponse) raceService.lockRosters(RACE,
            new LockRostersRequest(List.of(lockOf("t1", "a", "a", "b")),
                    8, "req-lock-fail")).body();
    assertThat(retried.locks().getFirst().rosterVersion()).isEqualTo(2);
}

